//! Opcode → JIT strategy. The table itself is generated by `build_opcodes.rs`
//! from the same `OP_CODES` list that produces the interpreter's opcode
//! metadata, so the two can never drift. See the generator for the policy for
//! each opcode.

use crate::bytecode::OP_COUNT_FINAL;

/// What the JIT may do with one opcode.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub(crate) enum JitPolicy {
    /// Translate inline into native machine code.
    Native = 0,
    /// Call the interpreter's Rust semantics from native code.
    Helper = 1,
    /// A function containing this opcode is never compiled (fail-closed).
    Reject = 2,
}

include!(concat!(env!("OUT_DIR"), "/jit-opcode-policy.rs"));

// The generated table must describe exactly the final opcode set. `OP_COUNT_FINAL`
// is `common` (and `short`) opcodes; the generator emits one entry per common
// opcode, which is the whole final set while `short_opcode` is off.
const _: () = assert!(JS_JIT_OPCODE_POLICY.len() == OP_COUNT_FINAL as usize);

/// Strategy for the final opcode `op`. Panics if `op` is out of range, which
/// can only happen on corrupt bytecode — the verifier rejects that separately.
#[allow(dead_code)]
pub(crate) const fn policy_for(op: u8) -> JitPolicy {
    JS_JIT_OPCODE_POLICY[op as usize]
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::bytecode::opcodes;

    #[test]
    fn table_is_indexed_by_final_opcode() {
        assert_eq!(policy_for(opcodes::OP_push_i32), JitPolicy::Native);
        assert_eq!(policy_for(opcodes::OP_add), JitPolicy::Helper);
        assert_eq!(policy_for(opcodes::OP_return), JitPolicy::Native);
    }

    #[test]
    fn yield_is_rejected() {
        assert_eq!(policy_for(opcodes::OP_yield), JitPolicy::Reject);
    }
}
